var mySize, angle;
var seed = Math.random() * 2965;
var color1;

let colors4 = "8c75ff-c553d2-2dfd60-2788f5-23054f".split("-").map((a) => "#" + a);
let colors5 = "f21252-8834f1-c4dd92-184fd3-f9fee2".split("-").map((a) => "#" + a);
let colors6 = "2E294E-541388-F1E9DA-FFD400-D90368".split("-").map((a) => "#" + a);
let colors7 = "1b1b1b-292929-f3f3f3-222222-ff0000".split("-").map((a) => "#" + a);
let colors8 = "e9baaa-ffa07a-164555-ffe1d0-acd9e7".split("-").map((a) => "#" + a);
let colorbg = "ffffff".split("-").map((a) => "#" + a);
let colorbg2 = "ffffff01".split("-").map((a) => "#" + a);
var t, timer;
var color_setup;

function setup() {
	randomSeed(seed);
	pixelDensity(5);
	mySize = max(windowWidth, windowHeight);
	createCanvas(windowWidth, windowHeight);
	// colorMode(HSB, 360,100,100,100);
	background("#ffffff");
	t = timer = 0;
	rez = c = n = 0.01;
	color_setup = random([colors4, colors5, colors6, colors7, colors8]);
	xOff = -50;
	yOff = -50;
	angle = 0;
}

function draw() {
	randomSeed(seed);
	// background(245);
	noFill();
	let plus = random(100, 200);
	for (let i = xOff; i < width - xOff; i += plus) {
		for (let j = yOff; j < height - yOff; j += plus) {
			for (let k = 0; k < 4; k++) {
				strokeCap(SQUARE);
				var n = noise(i * rez + t, j * rez + t);
				stroke(random(color_setup));

				if (n > 0.5) {
					push();
					translate(i, j);
					rotate(random([PI / 2, PI, -PI / 2, -PI]) + angle);
					let a = random(1, 5)
					strokeWeight(random(1));
					rect(0, 0, -plus / a, random(plus / a,plus / a/2));

					pop();
				} else {
					push();
					translate(i, j);
					rotate(random([PI / 2, PI, -PI / 2, -PI]) + angle);
					let b = random(1, 5)
					strokeWeight(random(1));
					rect(0, 0, plus / b, random(plus / b,plus / b/2));

					pop();
				}
			}
		}
	}
	if (angle < PI / 2) angle += TAU / 360 / random(2, 5) * random(1, 4);
	else noLoop();
}

function keyPressed() {
	//noLoop();
	saveCanvas("0217_untitled_2022", "png");
}

